using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Ivad.Ids;
using Ivad.Annotator;
partial class Tests {
 static Store FixtureStore(string root){var s=Store.Create(root,"范围测试","测试厂区");var e=s.Add("Equipment",new Dictionary<string,object>{{"name","设备"},{"project_id",s.Data.project_id}});s.Add("Camera",new Dictionary<string,object>{{"name","摄像头"},{"equipment_id",e.id}});s.Save();return s;}
 static void Cancelled(Action action,Func<string,bool> at){bool cancel=false,caught=false;Work.Configure(()=>cancel,message=>{if(at(message))cancel=true;});try{action();}catch(OperationCanceledException){caught=true;}finally{Work.Configure(null,null);}Assert(caught,"must throw cancellation");}
 static void Extended(string root){
  var s=FixtureStore(Path.Combine(root,"extended"));string camera=s.Data.entities.First(e=>e.kind=="Camera").id;var video=s.ImportVideo(Path.Combine(root,"sample.avi"),camera);
  Test("video/import-same-camera-idempotent",()=>{string before=Codec.Fingerprint(s.Data);Assert(s.ImportVideo(Path.Combine(root,"sample.avi"),camera).id==video.id,"stable video ID");Assert(Codec.Fingerprint(s.Data)==before,"no sequence bump");});
  Test("video/range-end-exclusive-PTS",()=>{Assert(Media.Extract(s.Root,video.id,.5,10,.5,2,null)==3,"range count");s.Reload();Assert(s.Data.entities.Where(e=>e.kind=="Frame").Select(e=>e.Number("pts_us")).SequenceEqual(new[]{500000.0,1000000,1500000}),"exact PTS");});
  Test("video/range-invalid-no-mutation",()=>{string before=Codec.HashFile(s.Manifest);Reject(()=>Media.Extract(s.Root,video.id,.5,10,2,1,null));Assert(Codec.HashFile(s.Manifest)==before,"unchanged");});
  Test("video/range-past-end-empty-not-codec-error",()=>{var empty=FixtureStore(Path.Combine(root,"past-end"));var v=empty.ImportVideo(Path.Combine(root,"sample.avi"),empty.Data.entities.First(e=>e.kind=="Camera").id);string before=Codec.HashFile(empty.Manifest);Assert(Media.Extract(empty.Root,v.id,1,10,100,200,null)==0,"empty range");Assert(Codec.HashFile(empty.Manifest)==before,"no mutation");});
  Test("video/resume-limit-without-duplicates-or-label-loss",()=>{var q=FixtureStore(Path.Combine(root,"resume-limit"));var v=q.ImportVideo(Path.Combine(root,"sample.avi"),q.Data.entities.First(e=>e.kind=="Camera").id);Assert(Media.Extract(q.Root,v.id,.5,2)==2,"first batch");q.Reload();var f=q.Data.entities.First(e=>e.kind=="Frame");q.Review(f.id,"normal","confirmed","retained");Assert(Media.Extract(q.Root,v.id,.5,2)==2&&Media.Extract(q.Root,v.id,.5,2)==2&&Media.Extract(q.Root,v.id,.5,2)==0,"resume batches");q.Reload();Assert(q.Data.entities.Count(e=>e.kind=="Frame")==6&&q.Find(f.id).Text("state")=="normal","labels retained");});
  Test("video/cancel-decode-no-partial-frames",()=>{string before=Codec.HashFile(s.Manifest);int count=Directory.GetFiles(Path.Combine(s.Root,"assets")).Length;Cancelled(()=>Media.Extract(s.Root,video.id,.5,10,0,3,null),m=>m.StartsWith("抽帧"));Assert(Codec.HashFile(s.Manifest)==before,"manifest unchanged");Assert(Directory.GetFiles(Path.Combine(s.Root,"assets")).Length==count,"asset cleanup");Assert(Directory.GetDirectories(s.Root,".frames-*").Length==0,"stage cleanup");});
  Test("video/retry-after-cancel-retains-existing",()=>{Assert(Media.Extract(s.Root,video.id,.5,10)==3,"remaining frames");s.Reload();Assert(s.Data.entities.Count(e=>e.kind=="Frame")==6,"no duplicates");});
  var frame=s.Data.entities.First(e=>e.kind=="Frame");var fault=s.Add("Fault",new Dictionary<string,object>{{"name","故障"},{"taxonomy_version",1}});s.Save();
  Test("geometry/edit-box-polygon-ROI-reopen",()=>{var box=s.AddAnnotation(frame.id,fault.id,"box",new[]{1.0,1,12,12},false);s.EditGeometry(box.id,new[]{5.0,5,20,20},"editor");s.EditGeometry(box.id,new[]{5.0,5,30,30},"editor");var poly=s.AddAnnotation(frame.id,fault.id,"polygon",new[]{2.0,2,30,2,30,30},false);s.EditGeometry(poly.id,new[]{3.0,3,35,3,35,35},"editor");var roi=s.AddAnnotation(frame.id,"","polygon",new[]{0.0,0,60,0,60,40},true);s.EditGeometry(roi.id,new[]{1.0,1,55,1,55,38},"editor");var restored=new Store(s.Root);Assert(restored.Find(box.id).revision==3,"box revisions");Assert(restored.Find(roi.id).Text("camera_id")==camera,"ROI association");Assert(Codec.Json(restored.Find(poly.id).data["points"])=="[3,3,35,3,35,35]","edited polygon");});
  Test("geometry/soft-delete-retains-history",()=>{var a=s.AddAnnotation(frame.id,fault.id,"box",new[]{1.0,1,2,2},false);s.DeleteGeometry(a.id,"editor");s.Reload();Assert(s.Find(a.id).Text("deleted")=="True"&&s.Data.entities.Count(e=>e.kind=="Revision"&&e.Text("entity_id")==a.id)==2,"history preserved");});
  Test("geometry/invalid-edit-no-disk-change",()=>{string before=Codec.HashFile(s.Manifest);var a=s.Data.entities.First(e=>e.kind=="Annotation");Reject(()=>s.EditGeometry(a.id,new[]{5.0,5,5,5},"editor"));Assert(Codec.HashFile(s.Manifest)==before,"unchanged");s.Reload();});
  Test("review/all-states-reopen-latest",()=>{foreach(string state in new[]{"normal","abnormal","unknown"}){s.Review(frame.id,state,"confirmed","editor");var r=new Store(s.Root);Assert(r.Find(frame.id).Text("state")==state,"state persisted");Assert(r.Data.entities.Last(e=>e.kind=="Review").Text("reviewer")=="editor","review persisted");}});
  Test("validation/PTS-units-and-duplicate",()=>{var d=Codec.Clone(s.Data);d.entities.First(e=>e.kind=="Frame").data["pts_us"]=123;Reject(()=>Rules.Validate(d));d=Codec.Clone(s.Data);var dup=Codec.Parse<Entity>(Codec.Json(d.entities.First(e=>e.kind=="Frame")));dup.id=Guid.NewGuid().ToString();d.entities.Add(dup);Reject(()=>Rules.Validate(d));});
  string pack=Path.Combine(root,"extended.ids.zip"),receiver=Path.Combine(root,"extended-receiver");Document baseline=null;
  Test("package/full-all-fields-hashes-idempotent",()=>{Packages.Export(s,pack,null);baseline=Codec.Clone(s.Data);var r=Packages.Import(pack,receiver);var repeat=Packages.Import(pack,receiver);Assert(Codec.Fingerprint(r.Data)==Codec.Fingerprint(s.Data)&&Codec.Fingerprint(repeat.Data)==Codec.Fingerprint(s.Data),"all entity fields/counts/UUIDs/hash metadata");Rules.VerifyAssets(repeat.Data,repeat.Root);});
  Test("package/delta-repeat-no-duplicates",()=>{s.Review(frame.id,"normal","confirmed","review2");string delta=Path.Combine(root,"extended-delta.zip");Packages.Export(s,delta,baseline);Packages.Import(delta,receiver);var repeat=Packages.Import(delta,receiver);Assert(Codec.Fingerprint(repeat.Data)==Codec.Fingerprint(s.Data),"repeat delta exact equality");});
  Test("package/same-size-SHA256-tamper-rejected",()=>{string bad=Path.Combine(root,"same-size-tamper.zip");File.Copy(pack,bad);using(var z=System.IO.Compression.ZipFile.Open(bad,System.IO.Compression.ZipArchiveMode.Update)){var entry=z.Entries.First(e=>e.FullName.StartsWith("assets/"));string name=entry.FullName;byte[] bytes;using(var input=entry.Open())using(var ms=new MemoryStream()){input.CopyTo(ms);bytes=ms.ToArray();}bytes[0]^=0x7F;entry.Delete();using(var output=z.CreateEntry(name).Open())output.Write(bytes,0,bytes.Length);}bool hashRejected=false;try{Packages.Import(bad,Path.Combine(root,"same-size-target"));}catch(InvalidDataException ex){hashRejected=ex.Message.Contains("哈希");}Assert(hashRejected,"must detect hash, not merely size/CRC");});
  Test("package/late-commit-failure-rolls-back-owned-files",()=>{string target=Path.Combine(root,"late-commit-failure");Directory.CreateDirectory(target);var asset=baseline.assets.Last();string existing=Rules.SafePath(target,asset.path);Directory.CreateDirectory(Path.GetDirectoryName(existing));File.WriteAllText(existing,"pre-existing user file must survive");string before=Codec.HashFile(existing);Reject(()=>Packages.Import(pack,target));Assert(!File.Exists(Path.Combine(target,"project.ids.json")),"no manifest commit");Assert(Directory.GetFiles(Path.Combine(target,"assets")).Length==1&&Codec.HashFile(existing)==before,"only newly moved files removed, pre-existing file intact");Assert(Directory.GetDirectories(target,".import-*").Length==0,"stage removed");});
  Test("package/export-cancel-cleans-temp",()=>{string p=Path.Combine(root,"cancel-export.zip"),before=Codec.HashFile(s.Manifest);Cancelled(()=>Packages.Export(s,p,null),m=>m.StartsWith("导出"));Assert(!File.Exists(p)&&Directory.GetFiles(root,"cancel-export.zip.*.tmp").Length==0,"no output or staging");Assert(Codec.HashFile(s.Manifest)==before,"source unchanged");});
  Test("package/import-cancel-rolls-back",()=>{string target=Path.Combine(root,"cancel-import");Cancelled(()=>Packages.Import(pack,target),m=>m.StartsWith("导入"));Assert(!File.Exists(Path.Combine(target,"project.ids.json"))&&!Directory.Exists(Path.Combine(target,"assets")),"no commit");Assert(Directory.GetDirectories(target,".import-*").Length==0,"staging cleaned");});
  Test("video/import-copy-cancel-cleans-temp",()=>{string p=Path.Combine(root,"large.avi");using(var f=new FileStream(p,FileMode.CreateNew)){f.SetLength(4*1024*1024);}int before=s.Data.assets.Count;Cancelled(()=>s.ImportVideo(p,camera),m=>m.StartsWith("复制资产"));Assert(s.Data.assets.Count==before,"manifest unchanged");Assert(Directory.GetFiles(Path.Combine(s.Root,"assets"),"*.tmp").Length==0,"partial copy cleaned");});
  Test("video/corrupt-input-fails-preserves-project",()=>{string p=Path.Combine(root,"corrupt.mp4");File.WriteAllText(p,"not a media file");var v=s.ImportVideo(p,camera);string before=Codec.HashFile(s.Manifest);Reject(()=>Media.Extract(s.Root,v.id,1,10));Assert(Codec.HashFile(s.Manifest)==before,"source retained, annotations untouched");Assert(Directory.GetDirectories(s.Root,".frames-*").Length==0,"staging cleaned");});
  Test("video/H264-MP4-real-encode-decode",()=>{long[] pts=Enumerable.Range(0,12).Select(i=>i*2500000L).ToArray();string p=Path.Combine(root,"h264.mp4");MediaFixtures.Encode(p,pts,2500000,false);var v=s.ImportVideo(p,camera);Assert(Media.Extract(s.Root,v.id,.25,100)==12,"12 H264 frames");s.Reload();Assert(s.Data.entities.Where(e=>e.kind=="Frame"&&e.Text("video_id")==v.id).Select(e=>(long)e.Number("source_timestamp_100ns")).SequenceEqual(pts),"H264 PTS exact");});
  Test("video/truncated-real-MP4-fails-without-loss",()=>{byte[] good=File.ReadAllBytes(Path.Combine(root,"h264.mp4"));string p=Path.Combine(root,"truncated-h264.mp4");File.WriteAllBytes(p,good.Take(good.Length/2).ToArray());var v=s.ImportVideo(p,camera);string before=Codec.HashFile(s.Manifest);Reject(()=>Media.Extract(s.Root,v.id,1,10));Assert(Codec.HashFile(s.Manifest)==before,"no annotation loss");});
  Test("video/VFR-H264-exact-PTS",()=>{long[] pts={0,1000000,4000000,12000000,12500000,22000000};string p=Path.Combine(root,"vfr.mp4");MediaFixtures.Encode(p,pts,500000,false);var v=s.ImportVideo(p,camera);Assert(Media.Extract(s.Root,v.id,.001,100)==pts.Length,"VFR count");s.Reload();Assert(s.Data.entities.Where(e=>e.kind=="Frame"&&e.Text("video_id")==v.id).Select(e=>(long)e.Number("source_timestamp_100ns")).SequenceEqual(pts),"VFR sample timestamps exact");});
  Test("video/MOV-QuickTime-brand-H264",()=>{string p=Path.Combine(root,"h264.mov");FixtureContainers.Mov(Path.Combine(root,"h264.mp4"),p);var v=s.ImportVideo(p,camera);Assert(Media.Extract(s.Root,v.id,.25,100)==12,"MOV frames");s.Reload();});
  Test("video/MKV-Matroska-H264",()=>{string p=Path.Combine(root,"h264.mkv");FixtureContainers.Mkv(Path.Combine(root,"h264.mp4"),p);var v=s.ImportVideo(p,camera);Assert(Media.Extract(s.Root,v.id,.25,100)==12,"MKV frames");s.Reload();Assert(s.Data.entities.Where(e=>e.kind=="Frame"&&e.Text("video_id")==v.id).Last().Number("pts_us")==2750000,"MKV timestamps");});
  Test("video/long-30min-H264-range-and-PTS",()=>{string p=Path.Combine(root,"long-30min.mp4");long[] pts=Enumerable.Range(0,1800).Select(i=>i*10000000L).ToArray();MediaFixtures.Encode(p,pts,10000000,false);var v=s.ImportVideo(p,camera);Assert(Media.Extract(s.Root,v.id,60,100)==30,"30 minute samples");Assert(Media.Extract(s.Root,v.id,1,100,1795,1800,null)==5,"tail range");s.Reload();Assert(s.Data.entities.Where(e=>e.kind=="Frame"&&e.Text("video_id")==v.id).Last().Number("pts_us")==1799000000,"tail exact PTS");});
  Test("video/long-1080p-30min-H264",()=>{var timer=System.Diagnostics.Stopwatch.StartNew();string p=Path.Combine(root,"long-1080p-30min.mp4");MediaFixtures.Encode(p,Enumerable.Range(0,1800).Select(i=>i*10000000L).ToArray(),10000000,false,1920,1080);long encodeMs=timer.ElapsedMilliseconds;var v=s.ImportVideo(p,camera);Assert(Media.Extract(s.Root,v.id,60,100)==30,"1080p minute samples");s.Reload();var fs=s.Data.entities.Where(e=>e.kind=="Frame"&&e.Text("video_id")==v.id).ToArray();Assert(fs.All(e=>e.Number("width")==1920&&e.Number("height")==1080)&&fs.Last().Number("pts_us")==1740000000,"resolution and PTS");File.WriteAllText(Path.Combine(root,"long-video-metrics.json"),Codec.Json(new{status="PASS",width=1920,height=1080,duration_seconds=1800,encoded_frames=1800,source_fps=1,extracted_frames=30,encode_ms=encodeMs,import_decode_save_ms=timer.ElapsedMilliseconds-encodeMs,bytes=new FileInfo(p).Length,gui_responsiveness="NOT TESTED",scope="synthetic 1 fps, not high bitrate surveillance stress"}));});
  Action<string> workerLog=message=>File.AppendAllText(Path.Combine(root,"worker-process.log"),DateTime.UtcNow.ToString("o")+" "+message+Environment.NewLine);
  Test("worker/actual-child-process-range",()=>{var v=s.Data.entities.First(e=>e.kind=="Video"&&e.Text("original_name")=="long-30min.mp4");VideoJobs.Run(s.Root,v.id,new[]{1.0,100,103,10},workerLog,Path.Combine(AppDomain.CurrentDomain.BaseDirectory,File.Exists(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"IVAD.Annotator.exe"))?"IVAD.Annotator.exe":"Ivad.Annotator.Dev.exe"));s.Reload();Assert(s.Data.entities.Count(e=>e.kind=="Frame"&&e.Text("video_id")==v.id&&e.Number("pts_us")>=100000000&&e.Number("pts_us")<103000000)==3,"child args/range persisted");Assert(Directory.GetDirectories(Path.Combine(s.Root,".jobs")).Length==0,"job cleanup");});
  Test("worker/actual-child-cancel-rollback",()=>{var v=s.Data.entities.First(e=>e.kind=="Video"&&e.Text("original_name")=="long-1080p-30min.mp4");string before=Codec.HashFile(s.Manifest);int assets=Directory.GetFiles(Path.Combine(s.Root,"assets")).Length;Cancelled(()=>VideoJobs.Run(s.Root,v.id,new[]{1.0,0,1800,5000},workerLog,Path.Combine(AppDomain.CurrentDomain.BaseDirectory,File.Exists(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"IVAD.Annotator.exe"))?"IVAD.Annotator.exe":"Ivad.Annotator.Dev.exe")),m=>true);Assert(Codec.HashFile(s.Manifest)==before,"no partial commit");Assert(Directory.GetFiles(Path.Combine(s.Root,"assets")).Length==assets,"no orphan created assets");Assert(Directory.GetDirectories(Path.Combine(s.Root,".jobs")).Length==0,"job cleanup");});
  Test("worker/corrupt-input-recovery",()=>{var v=s.Data.entities.First(e=>e.kind=="Video"&&e.Text("original_name")=="corrupt.mp4");string before=Codec.HashFile(s.Manifest);Reject(()=>VideoJobs.Run(s.Root,v.id,new[]{1.0,0,10,10},workerLog,Path.Combine(AppDomain.CurrentDomain.BaseDirectory,File.Exists(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"IVAD.Annotator.exe"))?"IVAD.Annotator.exe":"Ivad.Annotator.Dev.exe")));Assert(Codec.HashFile(s.Manifest)==before,"no annotation loss");Assert(Directory.GetDirectories(Path.Combine(s.Root,".jobs")).Length==0,"failed job cleanup");});
  Test("storage/cleanup-preserves-committed-assets",()=>{string p=Rules.SafePath(s.Root,s.Data.assets[0].path);Store.CleanupOwned(s.Root,new[]{p});Assert(File.Exists(p),"never remove referenced asset");Reject(()=>Store.CleanupOwned(s.Root,new[]{Path.Combine(root,"sample.avi")}));Assert(File.Exists(Path.Combine(root,"sample.avi")),"outside ownership rejected");});
  Test("storage/cancel-at-commit-cleans-created-assets",()=>{var clean=FixtureStore(Path.Combine(root,"cancel-commit"));string c=clean.Data.entities.First(e=>e.kind=="Camera").id;var v=clean.ImportVideo(Path.Combine(root,"sample.avi"),c);int before=Directory.GetFiles(Path.Combine(clean.Root,"assets")).Length;bool copied=false;Cancelled(()=>Media.Extract(clean.Root,v.id,.5,10),m=>{if(m!="提交前校验资产")return false;copied=Directory.GetFiles(Path.Combine(clean.Root,"assets")).Length>before;return true;});Assert(copied,"cancel must occur after creating assets");Assert(new Store(clean.Root).Data.entities.Count(e=>e.kind=="Frame")==0,"uncommitted frames absent");Assert(Directory.GetFiles(Path.Combine(clean.Root,"assets")).Length==before,"created asset rollback");});
  string hevc=Path.Combine(root,"hevc.mp4");bool encoded=false;try{MediaFixtures.Encode(hevc,Enumerable.Range(0,12).Select(i=>i*2500000L).ToArray(),2500000,true);encoded=true;}catch(Exception ex){File.WriteAllText(Path.Combine(root,"hevc-environment.json"),Codec.Json(new{status="NOT TESTED",phase="fixture encoding",error=ex.ToString(),meaning="No valid HEVC fixture generated; decoder support not inferred; no codec installed"}));}
  if(encoded)Test("video/HEVC-MP4-actual",()=>{var v=s.ImportVideo(hevc,camera);Assert(Media.Extract(s.Root,v.id,.25,100)==12,"HEVC frames");s.Reload();File.WriteAllText(Path.Combine(root,"hevc-environment.json"),Codec.Json(new{status="PASS",phase="actual encode and decode",frames=12}));});
  Test("package/final-complete-project-all-fields-assets",()=>{string p=Path.Combine(root,"final-complete.ids.zip"),target=Path.Combine(root,"final-restored");Packages.Export(s,p,null);var restored=Packages.Import(p,target);restored=Packages.Import(p,target);string source=Codec.Fingerprint(s.Data),dest=Codec.Fingerprint(restored.Data);Assert(source==dest,"full metadata equality including coordinates/categories/ROI/associations/reviews");Rules.VerifyAssets(restored.Data,restored.Root);File.WriteAllText(Path.Combine(root,"ids-roundtrip.json"),Codec.Json(new{status="PASS",mode="actual service / filesystem; real GUI NOT TESTED",source_sha256=source,restored_sha256=dest,package_sha256=Codec.HashFile(p),asset_count=s.Data.assets.Count,entity_counts=s.Data.entities.GroupBy(e=>e.kind).ToDictionary(g=>g.Key,g=>g.Count()),repeated_import="idempotent",assets_verified=true}));});
  File.WriteAllText(Path.Combine(root,"media-fixtures.json"),Codec.Json(Directory.GetFiles(root).Where(p=>new[]{".avi",".mp4",".mov",".mkv"}.Contains(Path.GetExtension(p))).Select(p=>new{file=Path.GetFileName(p),bytes=new FileInfo(p).Length,sha256=Codec.HashFile(p),source="Self-authored synthetic fixture / existing Windows Media Foundation; no external media or codecs",distribution="test only, excluded"}).ToArray()));
 }
